import { defineTool as defineTool2, ToolError as ToolError2 } from "npm:@lovable.dev/mcp-js@3.4.0";
import { z as z2 } from "npm:zod@^4.6.7";
var measurement_summary_default = defineTool2({
  name: "measurement_summary",
  title: "Heart rate summary",
  description: "Summarizes the signed-in user's heart rate over the last N days: average, minimum, maximum and number of measurements.",
  inputSchema: {
    days: z2.number().int().min(1).max(365).default(30).describe("Number of days to look back (1-365).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ days }, ctx) => {
    const supabase = supabaseForUser(ctx);
    const since = new Date(Date.now() - days * 24 * 60 * 60 * 1e3).toISOString();
    const { data, error } = await supabase.from("measurements").select("heart_rate, quality, measured_at").gte("measured_at", since).order("measured_at", { ascending: false });
    if (error) throw new ToolError2(`No se pudo calcular el resumen: ${error.message}`);
    const rows = data ?? [];
    if (rows.length === 0) {
      return {
        content: [{ type: "text", text: `No hay mediciones en los \xFAltimos ${days} d\xEDas.` }],
        structuredContent: {
          days,
          count: 0,
          avgHeartRateBpm: null,
          minHeartRateBpm: null,
          maxHeartRateBpm: null,
          avgSignalQualityPercent: null
        }
      };
    }
    const hrs = rows.map((r) => r.heart_rate);
    const qualities = rows.map((r) => r.quality);
    const avg = (xs) => xs.reduce((a, b) => a + b, 0) / xs.length;
    const summary = {
      days,
      count: rows.length,
      avgHeartRateBpm: Math.round(avg(hrs) * 10) / 10,
      minHeartRateBpm: Math.min(...hrs),
      maxHeartRateBpm: Math.max(...hrs),
      avgSignalQualityPercent: Math.round(avg(qualities) * 10) / 10
    };
    return {
      content: [
        {
          type: "text",
          text: `Resumen de ${summary.count} mediciones en ${days} d\xEDas: pulso medio ${summary.avgHeartRateBpm} lpm (m\xEDn ${summary.minHeartRateBpm}, m\xE1x ${summary.maxHeartRateBpm}), calidad media de se\xF1al ${summary.avgSignalQualityPercent}%.`
        }
      ],
      structuredContent: summary
    };
  }
});

